// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon, ChevronDownIcon, CopyIcon } from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import {
  BASES,
  CAPTIONS,
  DECIMAL_ROW,
  ERROR_CODE,
  FIXED,
  LABELS,
  MODE,
  ROW_LABELS,
  SCENES,
  TYPO,
  type Base,
} from './script'

const build: Build = ({ tl, q, step, final, move, click, type, scramble, wait, cursorOut }) => {
  const fill = (values: string[]) =>
    values.forEach((value, index) =>
      scramble(`value-${index}`, value, {
        at: index === 0 ? '<' : '<0.05',
        duration: 0.5,
        chars: '0123456789abcdef',
      }),
    )
  const base = (next: Base) => {
    move('base', { ax: 0.4 })
    click('base')
    tl.fromTo(
      q('base-menu'),
      { opacity: 0, y: -4 },
      { opacity: 1, y: 0, duration: 0.2, immediateRender: false },
      '<',
    )
    const index = BASES.indexOf(next)
    move(`base-item-${index}`, { ax: 0.3, at: '+=0.15' })
    click(`base-item-${index}`)
    tl.to(q('base-menu'), { opacity: 0, duration: 0.15 }, '+=0.1')
    tl.set(q('base-value'), { text: LABELS[next] }, '<')
  }
  const selectAll = () => {
    move('input', { ax: 0.3 })
    click('input')
    tl.to(q('in-text'), { backgroundColor: 'rgba(56,189,248,0.35)', duration: 0.1 }, '+=0.1')
    tl.set(q('in-text'), { text: '', backgroundColor: 'rgba(56,189,248,0)' }, '+=0.25')
  }
  const key = (label: string) => {
    tl.set(q('key'), { text: label }, '<')
    tl.fromTo(
      q('key'),
      { opacity: 1, y: 0 },
      { opacity: 0, y: -6, duration: 0.5, delay: 0.3, immediateRender: false },
      '<',
    )
  }

  step(0)
  move('input', { at: 0.3, ax: 0.3 })
  click('input')
  type('in-text', MODE.input, { speed: 0.12 })
  tl.to(q('rows'), { opacity: 1, duration: 0.2 }, '<0.1')
  fill(SCENES.mode)
  tl.to(q('row-1'), { borderColor: 'rgba(251,191,36,0.7)', duration: 0.25 }, '+=0.2')

  step(1, '+=0.5')
  tl.to(q('row-1'), { borderColor: 'var(--demo-tint-8)', duration: 0.2 }, '<')
  base(ERROR_CODE.base)
  selectAll()
  type('in-text', ERROR_CODE.input, { speed: 0.05 })
  fill(SCENES.errorCode)
  move(`copy-${DECIMAL_ROW}`, { at: '+=0.4' })
  click(`copy-${DECIMAL_ROW}`)
  tl.to(q(`copy-icon-${DECIMAL_ROW}`), { opacity: 0, duration: 0.1 }, '<')
  tl.fromTo(
    q(`copied-${DECIMAL_ROW}`),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(3)', immediateRender: false },
    '<',
  )

  step(2, '+=0.5')
  tl.to(q(`copied-${DECIMAL_ROW}`), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q(`copy-icon-${DECIMAL_ROW}`), { opacity: 1, duration: 0.15 }, '<')
  selectAll()
  tl.to(q('rows'), { opacity: 0, duration: 0.15 }, '<')
  base(FIXED.base)
  move('input', { ax: 0.3 })
  type('in-text', FIXED.input, { speed: 0.12 })
  tl.to(q('rows'), { opacity: 1, duration: 0.2 }, '<0.1')
  fill(SCENES.fixed)
  type('in-more', TYPO.input.slice(FIXED.input.length), { at: '+=0.4' })
  tl.to(q('rows'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('error'), { opacity: 1, duration: 0.2 }, '<')
  tl.to({}, { duration: 1.2 })
  key('⌫ Backspace')
  tl.set(q('in-more'), { text: '' }, '<')
  tl.to(q('error'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('rows'), { opacity: 1, duration: 0.2 }, '<')
  cursorOut('+=0.4')
  final()
  wait(1.2)

  tl.set([q('rows'), q('error'), q('base-menu'), q('key')], { opacity: 0 }, 0)
  tl.set([q('in-text'), q('in-more')], { text: '' }, 0)
}

export default function Demo() {
  return (
    <DemoStage
      label={`Base Converter showing ${MODE.input} in binary, octal, decimal and hex, reading ${ERROR_CODE.input} as ${SCENES.errorCode[DECIMAL_ROW]}, and rejecting a 2 in a binary number`}
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex flex-col gap-2.5">
          <div className="relative flex items-center gap-1.5">
            <span
              data-d="input"
              className="flex h-7 min-w-0 flex-1 items-center rounded-md border border-line-strong bg-canvas/80 px-2 font-mono text-[11px] text-ink"
            >
              <span data-d="in-text" />
              <span data-d="in-more" />
              <span className="ml-px h-3.5 w-px animate-pulse bg-ink-soft" />
            </span>
            <span className="relative">
              <span
                data-d="base"
                className="flex h-7 w-32 items-center justify-between rounded-md border border-line-strong bg-canvas/80 px-2 text-[10px] text-ink"
              >
                <span data-d="base-value">{LABELS[MODE.base]}</span>
                <ChevronDownIcon className="size-3 text-muted" />
              </span>
              <span
                data-d="base-menu"
                className="absolute right-0 top-full z-10 mt-1 w-32 rounded-md border border-line-strong bg-elevated p-0.5 opacity-0 shadow-2xl"
              >
                {BASES.map((entry, index) => (
                  <span
                    key={entry}
                    data-d={`base-item-${index}`}
                    className="block rounded px-2 text-[9.5px] leading-[17px] text-ink-soft"
                  >
                    {LABELS[entry]}
                  </span>
                ))}
              </span>
            </span>
            <span
              data-d="key"
              className="absolute -bottom-5 left-16 rounded border border-line-strong bg-elevated px-1.5 py-px font-mono text-[8.5px] text-ink opacity-0 shadow-lg"
            />
          </div>
          <div className="relative">
            <div
              data-d="error"
              className="absolute inset-x-0 top-0 rounded-md border border-[#f87171]/40 bg-[#f87171]/10 px-2.5 py-1.5 text-[10px] text-[#fca5a5] opacity-0"
            >
              {SCENES.typo}
            </div>
            <div data-d="rows" className="space-y-1 opacity-0">
              {ROW_LABELS.map((label, index) => (
                <div
                  key={label}
                  data-d={`row-${index}`}
                  className="flex h-7 items-center gap-2 rounded-md border border-line bg-ink/[0.03] px-2"
                >
                  <span className="w-[74px] shrink-0 text-[9.5px] font-medium text-muted">
                    {label}
                  </span>
                  <code
                    data-d={`value-${index}`}
                    className="min-w-0 flex-1 truncate font-mono text-[10px] text-ink"
                  />
                  <span data-d={`copy-${index}`} className="relative size-3 shrink-0 text-muted">
                    <CopyIcon data-d={`copy-icon-${index}`} className="absolute inset-0 size-3" />
                    <CheckIcon
                      data-d={`copied-${index}`}
                      className="absolute inset-0 size-3 text-[var(--accent)] opacity-0"
                    />
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
